import test from 'node:test';
import assert from 'node:assert/strict';
import { createCreditNote, nextCreditNoteNumber } from '../src/credits.js';

test('nextCreditNoteNumber returns 0001 when no credit notes exist', () => {
  const number = nextCreditNoteNumber([], '2026-10-07');
  assert.equal(number, 'CN-2026-0001');
});

test('nextCreditNoteNumber increments counter for same year', () => {
  const existing = ['CN-2026-0001', 'CN-2026-0002'];
  const number = nextCreditNoteNumber(existing, '2026-10-15');
  assert.equal(number, 'CN-2026-0003');
});

test('nextCreditNoteNumber restarts at 0001 for a new year', () => {
  const existing = ['CN-2025-0050'];
  const number = nextCreditNoteNumber(existing, '2026-01-01');
  assert.equal(number, 'CN-2026-0001');
});

test('nextCreditNoteNumber ignores invoice numbers', () => {
  const existing = ['INV-2026-0001', 'INV-2026-0002', 'CN-2026-0005'];
  const number = nextCreditNoteNumber(existing, '2026-10-07');
  assert.equal(number, 'CN-2026-0006');
});

test('nextCreditNoteNumber handles mixed numbers in any order', () => {
  const existing = ['INV-2026-0001', 'CN-2026-0003', 'INV-2026-0002', 'CN-2026-0001'];
  const number = nextCreditNoteNumber(existing, '2026-10-07');
  assert.equal(number, 'CN-2026-0004');
});

test('createCreditNote creates credit note for issued invoice', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = createCreditNote(invoice, { amount: 50000, reason: 'Defect correction', date: '2026-10-20' }, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2026-0001');
  assert.equal(result.value.invoiceNumber, 'INV-2026-0001');
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.amount, 50000);
  assert.equal(result.value.reason, 'Defect correction');
  assert.equal(result.value.date, '2026-10-20');
});

test('createCreditNote creates credit note for partially_paid invoice', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'partially_paid',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
    payments: [{ amount: 50000, date: '2026-10-15' }],
  };

  const result = createCreditNote(invoice, { amount: 30000, reason: 'Partial refund', date: '2026-10-20' }, []);

  assert.equal(result.ok, true);
});

test('createCreditNote creates credit note for paid invoice', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'paid',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
    payments: [{ amount: 114950, date: '2026-10-15' }],
  };

  const result = createCreditNote(invoice, { amount: 50000, reason: 'Early payment discount reversal', date: '2026-10-20' }, []);

  assert.equal(result.ok, true);
});

test('createCreditNote reports NOT_ISSUED for draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = createCreditNote(invoice, { amount: 1000, reason: 'Test', date: '2026-10-20' }, []);

  assert.deepEqual(result, { ok: false, error: 'NOT_ISSUED' });
});

test('createCreditNote reports AMOUNT_INVALID for zero amount', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = createCreditNote(invoice, { amount: 0, reason: 'Test', date: '2026-10-20' }, []);

  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote reports AMOUNT_INVALID for negative amount', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = createCreditNote(invoice, { amount: -1000, reason: 'Test', date: '2026-10-20' }, []);

  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote reports AMOUNT_INVALID for fractional amount', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = createCreditNote(invoice, { amount: 1000.5, reason: 'Test', date: '2026-10-20' }, []);

  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote reports DATE_INVALID for invalid date', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = createCreditNote(invoice, { amount: 1000, reason: 'Test', date: 'not-a-date' }, []);

  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createCreditNote reports CREDIT_TOO_HIGH for amount exceeding invoice total', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = createCreditNote(invoice, { amount: 999999999, reason: 'Test', date: '2026-10-20' }, []);

  assert.deepEqual(result, { ok: false, error: 'CREDIT_TOO_HIGH' });
});

test('createCreditNote accepts amount equal to invoice total', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const invoiceTotal = 114950;
  const result = createCreditNote(invoice, { amount: invoiceTotal, reason: 'Full refund', date: '2026-10-20' }, []);

  assert.equal(result.ok, true);
});

test('createCreditNote with discount and VAT', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 100,
        unitPrice: 10000,
        vatRate: 21,
        discountPercent: 10,
      },
    ],
  };

  const result = createCreditNote(invoice, { amount: 100000, reason: 'Adjustment', date: '2026-10-20' }, []);

  assert.equal(result.ok, true);
});

test('createCreditNote generates next credit note number', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = createCreditNote(
    invoice,
    { amount: 50000, reason: 'Refund', date: '2026-10-20' },
    ['INV-2026-0001', 'CN-2026-0001', 'CN-2026-0002'],
  );

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2026-0003');
});

test('createCreditNote handles year boundary for numbering', () => {
  const invoice = {
    number: 'INV-2027-0001',
    customerId: 'C-001',
    issueDate: '2027-01-15',
    dueDate: '2027-02-14',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = createCreditNote(
    invoice,
    { amount: 10000, reason: 'Adjustment', date: '2027-01-20' },
    ['CN-2026-0050'],
  );

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2027-0001');
});

test('createCreditNote preserves invoice and credit note numbers separately', () => {
  const invoice = {
    number: 'INV-2026-0010',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = createCreditNote(
    invoice,
    { amount: 50000, reason: 'Refund', date: '2026-10-20' },
    ['INV-2026-0001', 'INV-2026-0002', 'INV-2026-0010', 'CN-2026-0001', 'CN-2026-0002'],
  );

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2026-0003');
});

